const env = Object.fromEntries(names.map(name => [name, Deno.env.get(name)]));
let gate;
try {
    gate = createGateHandler(loadConfig(env));
} catch (err) {
    console.error('[privatecaptcha-bunny] Invalid configuration:', err instanceof Error ? err.message : 'unknown');
    // Even if configuration is missing, do not forward unauthenticated traffic.
    gate = async () => new Response('PrivateCaptcha is not configured', {
        status: 503,
        headers: { 'Cache-Control': 'private, no-store', 'Content-Type': 'text/plain' },
    });
}

BunnySDK.net.http
    .servePullZone({ url: 'https://example.org' /* Local development only. Bunny uses Pull Zone origin in production. */ })
    .onClientRequest(({ request }) => gate(request));

